/** Past sessions with corrections, per-exercise trends and records, and the Strong and weight-history imports. */
final class WorkoutHistory {
    final WorkoutScreen screen;final MainActivity a;final AppUi ui;
    WorkoutHistory(WorkoutScreen s){screen=s;a=s.a;ui=s.ui;}

    /** Sessions grouped by month, newest first; a month opens to show its workouts. */
    void open(){WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"History");Button imp=ui.quietButton("Import",this::imports);s.body.addView(imp,WorkoutViews.gap(ui,10));LinkedHashMap<String,List<JSONObject>> months=new LinkedHashMap<>();for(JSONObject row:WorkoutStore.workouts(a)){JSONObject d=row.optJSONObject("data");String st=d.optString("status");if("active".equals(st)||"paused".equals(st)||"draft".equals(st))continue;LocalDate day=WorkoutStore.day(d);if(day.equals(LocalDate.MIN))continue;String key=day.format(java.time.format.DateTimeFormatter.ofPattern("MMMM yyyy"));if(!months.containsKey(key))months.put(key,new ArrayList<>());months.get(key).add(row);}if(months.isEmpty())s.body.addView(ui.detail("No sessions yet."));LinearLayout rows=ui.column();s.body.addView(rows);HashSet<String> open=new HashSet<>();if(!months.isEmpty())open.add(months.keySet().iterator().next());Runnable[] paint=new Runnable[1];paint[0]=()->{rows.removeAllViews();for(Map.Entry<String,List<JSONObject>> m:months.entrySet()){double volume=0;for(JSONObject r:m.getValue())volume+=volume(r.optJSONObject("data"));boolean show=open.contains(m.getKey());LinearLayout h=ui.row();h.setMinimumHeight(ui.dp(60));h.setPadding(ui.dp(14),ui.dp(6),ui.dp(10),ui.dp(6));h.setBackground(ui.pressable(ui.outline(ui.surface,16,ui.stroke,1),16));LinearLayout w=ui.column();w.addView(ui.type(m.getKey(),15,20,700,0,ui.text));w.addView(ui.type(m.getValue().size()+(m.getValue().size()==1?" workout":" workouts")+(volume>0?" · "+WorkoutUnits.load(a,volume)+" lifted":""),12.5f,17,400,0,ui.muted));h.addView(w,new LinearLayout.LayoutParams(0,-2,1));h.addView(MainParts.icon(ui,show?"up":"down",ui.muted),new LinearLayout.LayoutParams(ui.dp(18),ui.dp(18)));h.setOnClickListener(v->{if(!open.remove(m.getKey()))open.add(m.getKey());paint[0].run();});rows.addView(h,WorkoutViews.gap(ui,6));if(show)for(JSONObject r:m.getValue()){JSONObject d=r.optJSONObject("data");boolean skipped="skipped".equals(d.optString("status"));LocalDate day=WorkoutStore.day(d);rows.addView(WorkoutViews.row(ui,d.optString("name"),day.format(WorkoutScreen.SHORT)+(skipped?" · Rest":" · "+d.optLong("duration_seconds")/60+" min · "+WorkoutUnits.load(a,volume(d))),()->session(r.optString("id"))),WorkoutViews.gap(ui,6));}}};paint[0].run();s.show();}
    /** Working-set load × reps. Warm-ups don't count; dumbbell loads are per hand, as logged. */
    static double volume(JSONObject d){double v=0;JSONArray sets=d.optJSONArray("sets");for(int i=0;sets!=null&&i<sets.length();i++){JSONObject x=sets.optJSONObject(i);if("warmup".equals(x.optString("kind"))||"note".equals(x.optString("kind"))||!x.optBoolean("completed",true))continue;v+=x.optDouble("weight_kg",0)*x.optInt("reps",0);}return v;}
    void session(String id){JSONObject found=WorkoutStore.data(a,"workout",id);if(found==null)return;WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,found.optString("name"));paint(s,id);s.show();}
    private void paint(WorkoutViews.Sheet s,String id){s.body.removeAllViews();JSONObject d=WorkoutStore.data(a,"workout",id);if(d==null)return;LocalDate day=WorkoutStore.day(d);s.body.addView(ui.detail(day.format(WorkoutScreen.DAY)+" "+day.getYear()+" · "+WorkoutViews.clock(d.optLong("duration_seconds"))+(volume(d)>0?" · "+WorkoutUnits.load(a,volume(d))+" volume":"")),WorkoutViews.gap(ui,10));if(!d.optString("skip_reason").isEmpty())s.body.addView(ui.detail(d.optString("skip_reason")),WorkoutViews.gap(ui,10));LinkedHashMap<String,List<Integer>> groups=new LinkedHashMap<>();JSONArray sets=d.optJSONArray("sets");for(int i=0;sets!=null&&i<sets.length();i++){String e=sets.optJSONObject(i).optString("exercise_id");if(!groups.containsKey(e))groups.put(e,new ArrayList<>());groups.get(e).add(i);}
        for(Map.Entry<String,List<Integer>> g:groups.entrySet()){LinearLayout c=WorkoutViews.card(ui);TextView title=ui.type(WorkoutStore.exerciseName(a,g.getKey()),15,20,700,0,ui.accent);title.setOnClickListener(v->exercise(g.getKey()));c.addView(title,WorkoutViews.gap(ui,4));for(int i:g.getValue()){JSONObject x=sets.optJSONObject(i);TextView row=ui.type(line(x),14,22,400,0,ui.text);row.setContentDescription("Correct this set");final int at=i;row.setOnClickListener(v->correct(s,id,at));c.addView(row);}s.body.addView(c,WorkoutViews.gap(ui,8));}
        if(!d.optString("notes").isEmpty())s.body.addView(ui.type(d.optString("notes"),14,20,400,0,ui.muted),WorkoutViews.gap(ui,8));JSONObject src=d.optJSONObject("source");if(src!=null&&src.has("workout_number"))s.body.addView(ui.detail("Imported from Strong, workout "+src.optString("workout_number")),WorkoutViews.gap(ui,8));s.body.addView(ui.detail("Tap a set to correct it. Your original import stays unchanged on the server."),WorkoutViews.gap(ui,8));s.body.addView(ui.ghostButton("Delete workout",()->new AlertDialog.Builder(a).setTitle("Delete this workout?").setMessage("It leaves your history, records and ranks.").setPositiveButton("Delete",(x,i)->{WorkoutStore.delete(a,"workout",id);s.dialog.dismiss();screen.refresh();}).setNegativeButton("Keep",null).show()),WorkoutViews.gap(ui,8));JSONArray changes=d.optJSONArray("session_changes");for(int i=0;changes!=null&&i<changes.length();i++){JSONObject ch=changes.optJSONObject(i);s.body.addView(ui.type(ch.optString("reason",ch.optString("note")),12.5f,17,400,0,ui.muted));}}
    private String line(JSONObject x){String kind=x.optString("kind"),tag="working".equals(kind)?"":kind.substring(0,1).toUpperCase(Locale.ROOT)+"  ";if(x.has("distance_m")&&!x.isNull("distance_m"))return tag+WorkoutUnits.distance(a,x.optDouble("distance_m"))+" · "+WorkoutViews.clock(x.optLong("seconds"));String w=x.has("weight_kg")&&!x.isNull("weight_kg")?WorkoutUnits.load(a,x.optDouble("weight_kg"))+" × ":"";return tag+w+x.optInt("reps")+(x.has("rir")&&!x.isNull("rir")?" · "+WorkoutViews.kg(x.optDouble("rir"))+" RIR":"");}
    private void correct(WorkoutViews.Sheet s,String id,int index){JSONObject d=WorkoutStore.data(a,"workout",id);JSONObject x=d.optJSONArray("sets").optJSONObject(index);boolean run=x.has("distance_m")&&!x.isNull("distance_m");LinearLayout box=ui.column();box.setPadding(ui.dp(20),ui.dp(8),ui.dp(20),0);EditText w=ui.field(run?"Distance in "+WorkoutUnits.distanceLabel(a):"Weight in "+WorkoutUnits.loadLabel(a),run?WorkoutUnits.distanceNumber(a,x.optDouble("distance_m")):x.isNull("weight_kg")||!x.has("weight_kg")?"":WorkoutUnits.loadNumber(a,x.optDouble("weight_kg"))),r=ui.field(run?"Time, minutes:seconds":"Reps",run?WorkoutViews.clock(x.optLong("seconds")):x.isNull("reps")||!x.has("reps")?"":""+x.optInt("reps"));w.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);if(run)r.setInputType(InputType.TYPE_CLASS_DATETIME|InputType.TYPE_DATETIME_VARIATION_TIME);else r.setInputType(InputType.TYPE_CLASS_NUMBER);box.addView(w,WorkoutViews.gap(ui,6));box.addView(r);String[] kinds={"working","warmup","drop","failure"},labels={"Working","Warm-up","Drop","Failure"};final int[] pick={Math.max(0,Arrays.asList(kinds).indexOf(x.optString("kind")))};Button type=ui.quietButton(labels[pick[0]],null);type.setOnClickListener(v->new AlertDialog.Builder(a).setItems(labels,(y,i)->{pick[0]=i;type.setText(labels[i]);}).show());box.addView(type);new AlertDialog.Builder(a).setTitle("Correct set").setView(box).setPositiveButton("Save",(y,i)->{try{JSONObject copy=new JSONObject(d.toString());JSONObject set=copy.getJSONArray("sets").getJSONObject(index);String first=w.getText().toString().trim().replace(',','.'),second=r.getText().toString().trim();if(run){set.put("distance_m",WorkoutUnits.distanceIn(a,Double.parseDouble(first)));long seconds=0;for(String part:second.split(":"))seconds=seconds*60+Long.parseLong(part.trim());if(seconds<=0)throw new IllegalArgumentException();set.put("seconds",seconds);}else{if(first.isEmpty())set.remove("weight_kg");else set.put("weight_kg",WorkoutUnits.loadIn(a,Double.parseDouble(first)));if(second.isEmpty())set.remove("reps");else set.put("reps",Integer.parseInt(second));}set.put("kind",kinds[pick[0]]);WorkoutStore.put(a,"workout",id,copy);paint(s,id);screen.refresh();}catch(Exception e){Toast.makeText(a,"Check the numbers",Toast.LENGTH_SHORT).show();}}).setNegativeButton("Cancel",null).show();}

    void exercises(){WorkoutPlan.pick(screen,this::exercise);}
    /** Trend with the break left visible, today's form apart from all-time bests, and the rank if this lift has one. */
    void exercise(String id){JSONObject o=screen.overview();WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,WorkoutStore.exerciseName(a,id));JSONArray ranks=o.optJSONArray("lift_ranks");for(int i=0;ranks!=null&&i<ranks.length();i++){JSONObject r=ranks.optJSONObject(i);if(!id.equals(r.optString("exercise_id"))||!"ranked".equals(r.optString("status")))continue;int t=WorkoutViews.tier(r.optString("tier"));LinearLayout c=WorkoutViews.card(ui);LinearLayout h=ui.row();h.addView(new WorkoutViews.Crest(a,t,false),new LinearLayout.LayoutParams(ui.dp(42),ui.dp(47)));h.addView(ui.type(r.optString("tier")+" "+r.optInt("score"),20,26,800,0,WorkoutViews.color(t,ui.dark)),MainParts.weighted(ui,1,10,0,0,0));c.addView(h);if(r.has("next_tier")&&!r.isNull("next_tier"))c.addView(ui.type("Estimated max "+WorkoutUnits.load(a,r.optDouble("estimated_1rm_kg"))+". "+WorkoutUnits.load(a,r.optDouble("next_e1rm_kg"))+" reaches "+r.optString("next_tier")+".",13,18,400,0,ui.muted),MainParts.params(ui,-1,-2,0,6,0,0));s.body.addView(c,WorkoutViews.gap(ui,10));}
        ArrayList<double[]> points=new ArrayList<>(),volumes=new ArrayList<>();ArrayList<JSONObject[]> recent=new ArrayList<>();List<JSONObject> all=WorkoutStore.workouts(a);double top=0;for(int i=all.size()-1;i>=0;i--){JSONObject d=all.get(i).optJSONObject("data");if(!"completed".equals(d.optString("status")))continue;double best=0,sum=0;JSONObject bestSet=null;JSONArray sets=d.optJSONArray("sets");for(int k=0;sets!=null&&k<sets.length();k++){JSONObject x=sets.optJSONObject(k);if(!id.equals(x.optString("exercise_id"))||!x.optBoolean("completed",true))continue;if(WorkoutStore.cardio(a,id)&&!"working".equals(x.optString("kind")))continue;if(!"warmup".equals(x.optString("kind"))&&!"note".equals(x.optString("kind")))sum+=x.optDouble("weight_kg",0)*x.optInt("reps",0);double v=x.has("distance_m")&&!x.isNull("distance_m")&&x.optDouble("seconds",0)>0?x.optDouble("distance_m")/x.optDouble("seconds")*3.6:WorkoutStore.e1rm(x);if(v>best){best=v;bestSet=x;}}if(best>0&&!WorkoutStore.day(d).equals(LocalDate.MIN)){points.add(new double[]{WorkoutStore.day(d).toEpochDay(),best});if(sum>0)volumes.add(new double[]{WorkoutStore.day(d).toEpochDay(),sum});top=Math.max(top,best);recent.add(new JSONObject[]{d,bestSet});}}
        LinearLayout t=WorkoutViews.card(ui);t.addView(ui.type(WorkoutStore.cardio(a,id)?"Speed":"Estimated max",15,20,700,0,ui.text));if(points.size()<2)t.addView(ui.type("Log this a couple more times to see a trend.",13,18,400,0,ui.muted));else{WorkoutViews.Chart chart=new WorkoutViews.Chart(ui);chart.gap=45;chart.reference=top;chart.line(points.toArray(new double[0][]),ui.accent,2);t.addView(chart,MainParts.params(ui,-1,ui.dp(130),0,6,0,0));t.addView(ui.type("The flat dashed line is your best. Dashed joins are breaks of over 45 days.",11.5f,16,400,0,ui.muted));}s.body.addView(t,WorkoutViews.gap(ui,10));if(volumes.size()>1){LinearLayout v=WorkoutViews.card(ui);v.addView(ui.type("Volume per session",15,20,700,0,ui.text));WorkoutViews.Chart chart=new WorkoutViews.Chart(ui);chart.gap=45;chart.line(volumes.toArray(new double[0][]),ui.aurora[2],2);v.addView(chart,MainParts.params(ui,-1,ui.dp(110),0,6,0,0));s.body.addView(v,WorkoutViews.gap(ui,10));}
        JSONArray records=o.optJSONArray("exercise_records");for(int i=0;records!=null&&i<records.length();i++){JSONObject r=records.optJSONObject(i);if(!id.equals(r.optString("exercise_id")))continue;LinearLayout c=WorkoutViews.card(ui);c.addView(ui.type("Records",15,20,700,0,ui.text));JSONObject now=r.optJSONObject("recent"),ever=r.optJSONObject("historical");boolean hand="per_hand".equals(r.optString("load_convention"));c.addView(ui.type("Last 28 days",12.5f,17,600,0,ui.muted),MainParts.params(ui,-1,-2,0,6,0,0));record(c,now,hand);c.addView(ui.type("All-time",12.5f,17,600,0,ui.muted),MainParts.params(ui,-1,-2,0,8,0,0));record(c,ever,hand);s.body.addView(c,WorkoutViews.gap(ui,10));}
        s.body.addView(ui.label("Recent sessions"),WorkoutViews.gap(ui,6));for(int i=recent.size()-1;i>=Math.max(0,recent.size()-8);i--){JSONObject d=recent.get(i)[0];LocalDate day=WorkoutStore.day(d);s.body.addView(WorkoutViews.pair(ui,day.format(WorkoutScreen.SHORT)+" "+day.getYear(),line(recent.get(i)[1]),ui.muted));}s.show();}

    private void record(LinearLayout c,JSONObject w,boolean hand){if(w==null||w.length()==0){c.addView(ui.type("None",14,20,400,0,ui.muted));return;}JSONObject load=w.optJSONObject("best_load"),reps=w.optJSONObject("best_reps"),volume=w.optJSONObject("best_volume");String unit=hand?" each":"";if(load!=null)c.addView(WorkoutViews.pair(ui,"Heaviest · "+load.optString("date"),WorkoutUnits.load(a,load.optDouble("weight_kg"))+unit+" × "+load.optInt("reps"),ui.text));if(reps!=null)c.addView(WorkoutViews.pair(ui,"Most reps · "+reps.optString("date"),(reps.isNull("weight_kg")||!reps.has("weight_kg")?"":WorkoutUnits.load(a,reps.optDouble("weight_kg"))+unit+" × ")+reps.optInt("reps"),ui.text));if(volume!=null)c.addView(WorkoutViews.pair(ui,"Best set volume · "+volume.optString("date"),WorkoutUnits.load(a,volume.optDouble("kg_repetitions"))+(hand?" each side":""),ui.text));}
    /** Preview first; nothing is added until the owner confirms the counts. Imports are idempotent on the server. */
    void imports(){new AlertDialog.Builder(a).setTitle("Import").setItems(new String[]{"Strong workouts (CSV)","Weight history (CSV)"},(x,i)->WorkoutPicker.pick(a,"*/*",uri->preview(uri,i==0?"strong":"bodyweight"))).show();}
    private void preview(Uri uri,String format){Toast.makeText(a,"Checking the file…",Toast.LENGTH_SHORT).show();new Thread(()->{try{byte[] bytes=WorkoutPhotos.read(a,uri,32*1024*1024);String tz=java.net.URLEncoder.encode(ZoneId.systemDefault().getId(),"UTF-8");JSONObject r=new JSONObject(new String(Cloud.raw(a,"POST","workout/imports/"+format+"?commit=false&timezone="+tz,bytes,"text/csv"),"UTF-8"));a.runOnUiThread(()->confirm(bytes,format,tz,r));}catch(Exception e){a.runOnUiThread(()->Toast.makeText(a,"Couldn't read that file on your server.",Toast.LENGTH_LONG).show());}}).start();}
    private void confirm(byte[] bytes,String format,String tz,JSONObject r){StringBuilder b=new StringBuilder();for(Iterator<String> i=r.keys();i.hasNext();){String k=i.next();Object v=r.opt(k);if(v instanceof Number||v instanceof String&&((String)v).length()<40)b.append(k.replace('_',' ')).append(": ").append(v).append('\n');}new AlertDialog.Builder(a).setTitle("Import this file?").setMessage(b.toString().trim()).setPositiveButton("Import",(x,i)->new Thread(()->{String m;try{Cloud.raw(a,"POST","workout/imports/"+format+"?commit=true&timezone="+tz,bytes,"text/csv");m="Imported";}catch(Exception e){m="Import failed. Nothing was added.";}String t=m;a.runOnUiThread(()->{Toast.makeText(a,t,Toast.LENGTH_LONG).show();screen.refresh();});}).start()).setNegativeButton("Cancel",null).show();}
}
